+package com.example.customers.domain;
+
+import java.text.Normalizer;
+import java.util.Arrays;
+import java.util.Collections;
+import java.util.EnumSet;
+import java.util.List;
+import java.util.Locale;
+import java.util.Set;
+import java.util.function.Predicate;
+import java.util.regex.Pattern;
+
+/**
+ * How the customer list is narrowed down: free text matched against names, plus
+ * a set of statuses. Both parts are applied by the backend, never in the UI.
+ *
+ * <p>A customer matches when it satisfies both parts:
+ *
+ * <ul>
+ * <li>the text is split into whitespace-separated terms, and every term must
+ * occur in the customer's first name or last name, ignoring case and accents;
+ * <li>the status set, when not empty, must contain the customer's status.
+ * </ul>
+ *
+ * <p>An empty name and an empty status set match every customer, so
+ * {@link #NONE} is the unfiltered query.
+ *
+ * @param name     the text to match against names; never {@code null}
+ * @param statuses the statuses to show, empty meaning all of them
+ */
+public record CustomerFilter(String name, Set<CustomerStatus> statuses) {
+
+    /** The filter that matches every customer. */
+    public static final CustomerFilter NONE = new CustomerFilter("", Set.of());
+
+    private static final Pattern WHITESPACE = Pattern.compile("\\s+");
+    private static final Pattern DIACRITICS = Pattern.compile("\\p{M}+");
+
+    public CustomerFilter {
+        name = (name == null) ? "" : name;
+        statuses = (statuses == null || statuses.isEmpty())
+                ? Set.of()
+                : Collections.unmodifiableSet(EnumSet.copyOf(statuses));
+    }
+
+    /** The name filter as folded terms, all of which have to match. */
+    public List<String> nameTerms() {
+        if (name.isBlank()) {
+            return List.of();
+        }
+        return Arrays.stream(WHITESPACE.split(name.strip()))
+                .map(CustomerFilter::fold)
+                .toList();
+    }
+
+    /** Whether this filter lets every customer through. */
+    public boolean isEmpty() {
+        return statuses.isEmpty() && nameTerms().isEmpty();
+    }
+
+    /**
+     * Returns this filter as a predicate. The name terms are folded once, up
+     * front, so that a query over many rows does not redo that work per row.
+     */
+    public Predicate<Customer> asPredicate() {
+        List<String> terms = nameTerms();
+        Set<CustomerStatus> allowed = statuses;
+        return customer -> matchesStatus(customer, allowed) && matchesName(customer, terms);
+    }
+
+    private static boolean matchesStatus(Customer customer, Set<CustomerStatus> allowed) {
+        return allowed.isEmpty() || allowed.contains(customer.status());
+    }
+
+    private static boolean matchesName(Customer customer, List<String> terms) {
+        if (terms.isEmpty()) {
+            return true;
+        }
+        String firstName = fold(customer.firstName());
+        String lastName = fold(customer.lastName());
+        for (String term : terms) {
+            if (!firstName.contains(term) && !lastName.contains(term)) {
+                return false;
+            }
+        }
+        return true;
+    }
+
+    /**
+     * Folds text into the form names are compared in: accents decomposed and
+     * dropped, then lower case. So {@code Mäkinen}, {@code makinen} and
+     * {@code MÄKINEN} all fold to {@code makinen}.
+     */
+    public static String fold(String text) {
+        String decomposed = Normalizer.normalize(text, Normalizer.Form.NFD);
+        return DIACRITICS.matcher(decomposed).replaceAll("").toLowerCase(Locale.ROOT);
+    }
+}
