+package com.example.customers;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+import java.util.List;
+import java.util.Set;
+
+import com.example.customers.domain.Customer;
+import com.example.customers.domain.CustomerFilter;
+import com.example.customers.domain.CustomerStatus;
+
+import org.junit.jupiter.api.Test;
+
+/** What the backend considers a match. No Vaadin, no Spring. */
+class CustomerFilterTest {
+
+    private static final Customer ADA = customer("Ada", "Aaltonen", CustomerStatus.ACTIVE);
+    private static final Customer DAGNY = customer("Dagny", "Mäkinen", CustomerStatus.PENDING);
+    private static final Customer JOSEPHINE = customer("Joséphine", "Engberg", CustomerStatus.CLOSED);
+
+    @Test
+    void emptyFilterMatchesEverything() {
+        assertTrue(CustomerFilter.NONE.isEmpty());
+        assertTrue(matches(CustomerFilter.NONE, ADA));
+        assertTrue(matches(new CustomerFilter("   ", Set.of()), DAGNY));
+        assertTrue(matches(new CustomerFilter(null, null), JOSEPHINE));
+    }
+
+    @Test
+    void everyTermMustMatchAFirstOrLastName() {
+        assertTrue(matches(name("ada aal"), ADA));
+        assertTrue(matches(name("aal ada"), ADA));
+        assertTrue(matches(name("  ada   aal  "), ADA));
+        assertFalse(matches(name("ada virtanen"), ADA));
+        assertEquals(List.of("ada", "aal"), name(" ada  aal ").nameTerms());
+    }
+
+    @Test
+    void namesMatchIgnoringCaseAndAccents() {
+        assertTrue(matches(name("makinen"), DAGNY));
+        assertTrue(matches(name("MAKINEN"), DAGNY));
+        assertTrue(matches(name("mäkinen"), DAGNY));
+        assertTrue(matches(name("MÄKINEN"), DAGNY));
+        assertTrue(matches(name("josephine"), JOSEPHINE));
+        assertTrue(matches(name("joséphine"), JOSEPHINE));
+        assertFalse(matches(name("makinen"), ADA));
+    }
+
+    @Test
+    void statusesAreMatchedAsASet() {
+        assertTrue(matches(status(), ADA));
+        assertTrue(matches(status(CustomerStatus.ACTIVE), ADA));
+        assertFalse(matches(status(CustomerStatus.CLOSED), ADA));
+        assertTrue(matches(status(CustomerStatus.ACTIVE, CustomerStatus.CLOSED), JOSEPHINE));
+    }
+
+    @Test
+    void bothPartsHaveToMatch() {
+        CustomerFilter filter = new CustomerFilter("aal", Set.of(CustomerStatus.ACTIVE));
+        assertFalse(filter.isEmpty());
+        assertTrue(matches(filter, ADA));
+        assertFalse(matches(new CustomerFilter("aal", Set.of(CustomerStatus.PENDING)), ADA));
+    }
+
+    @Test
+    void filtersWithTheSameMeaningAreEqual() {
+        assertEquals(new CustomerFilter("vir", Set.of(CustomerStatus.ACTIVE, CustomerStatus.CLOSED)),
+                new CustomerFilter("vir", Set.of(CustomerStatus.CLOSED, CustomerStatus.ACTIVE)));
+        assertEquals(CustomerFilter.NONE, new CustomerFilter(null, null));
+    }
+
+    private static boolean matches(CustomerFilter filter, Customer customer) {
+        return filter.asPredicate().test(customer);
+    }
+
+    private static CustomerFilter name(String name) {
+        return new CustomerFilter(name, Set.of());
+    }
+
+    private static CustomerFilter status(CustomerStatus... statuses) {
+        return new CustomerFilter("", Set.of(statuses));
+    }
+
+    private static Customer customer(String firstName, String lastName, CustomerStatus status) {
+        return new Customer(1, firstName, lastName,
+                firstName.toLowerCase() + "@example.com", "Finland", status);
+    }
+}
