+    /**
+     * Applying a filter costs one count query and at most one page query: the
+     * summary and the grid share the count the backend reported. (Karibu's own
+     * {@code _size} / {@code _get} helpers query the backend again every time
+     * they are called, so this only measures the view itself.)
+     */
+    @Test
+    void applyingAFilterCostsOneCountAndOnePage() {
+        queryLog.clear();
+
+        _setValue(nameFilter(), "aaltonen");
+
+        assertEquals(List.of(15), queryLog.countQueries(),
+                "Applying a filter must ask the backend for the matching count exactly once");
+        assertTrue(queryLog.pageQueries().size() <= 1,
+                "Applying a filter ran " + queryLog.pageQueries().size() + " page queries");
+        assertTrue(queryLog.rowsFetched() <= CustomerRepository.MAX_PAGE_SIZE,
+                "Applying a filter pulled " + queryLog.rowsFetched() + " rows over");
+        assertEquals("Showing 15 of 500", summary().getText());
+    }
