+    /** The URL of the last {@code history.replaceState} the view asked for. */
+    private static String lastHistoryUrl() {
+        List<PendingJavaScriptInvocation> invocations =
+                UI.getCurrent().getInternals().dumpPendingJavaScriptInvocations();
+        for (int i = invocations.size() - 1; i >= 0; i--) {
+            PendingJavaScriptInvocation invocation = invocations.get(i);
+            String expression = invocation.getInvocation().getExpression();
+            if (expression.contains("replaceState") || expression.contains("vaadin-navigate")) {
+                return String.valueOf(invocation.getInvocation().getParameters().get(1));
+            }
+        }
+        return null;
+    }
